/* PDF mẫu cho trang preview `sd-preview-pdf` — nhúng base64 trong file .js để mở được bằng
   file:// (trình duyệt chặn fetch/XHR tới file://). Sinh bằng Chromium (print-to-PDF, font
   DejaVu Serif nhúng sẵn), 12 trang khổ Letter 612×792 như mẫu catalog `#c-preview-pdf`:
     contract — "Hợp đồng tín dụng hạn mức" (cụm "lãi suất" xuất hiện 3 lần: trang 1 ×2, trang 4 ×1)
     locked   — cùng nội dung, mã hoá AES-256, mật khẩu mở: 123456
   Dùng: viewer.source = sdDemoPdf('contract');  // Uint8Array mới mỗi lần gọi */
window.SD_DEMO_PDF_B64 = {
  contract: "",
  locked: ""
};
window.sdDemoPdf = function (name) {
  var b = atob(window.SD_DEMO_PDF_B64[name]);
  var u = new Uint8Array(b.length);
  for (var i = 0; i < b.length; i++) u[i] = b.charCodeAt(i);
  return u;
};
